/**
 * Raw navigation item definition (without runtime state like matched/status).
 * Used to define the static navigation structure.
 */
export interface NavItem {
  name: string;
  translate: string;
  icon: string;
  icon_width?: string;
  route?: string;
  tooltip: string;
  documentation_link: string;
  searchKeywords?: string[];
  children?: NavItem[];
  quickLink?: boolean;
}

export interface NavCategory {
  id: string;
  titleKey: string;
  titleFallback: string;
  descriptionKey: string;
  descriptionFallback: string;
  icon: string;
  iconColor: string;
  items: NavItem[];
}

