    // ──────────────────────────────────────────────
    // Helper to convert NavItem to SettingItem
    // ──────────────────────────────────────────────

    function toSettingItem(nav: NavItem): SettingItem {
      return {
        name: nav.name,
        label: nav.translate, // Will be translated by component via $t()
        translate: nav.translate,
        icon: nav.icon,
        icon_width: nav.icon_width,
        route: nav.route,
        tooltip: nav.tooltip,
        matched: true,
        documentation_link: nav.documentation_link,
        searchKeywords: nav.searchKeywords,
        children: nav.children ? nav.children.map(toSettingItem) : undefined,
      };
    }

